+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Set;
+import java.util.function.Predicate;
+
+/**
+ * The criteria the customer list is narrowed by. Understood by
+ * {@link CustomerRepository}, so that filtering happens in the backend and the
+ * grid keeps fetching one page at a time.
+ *
+ * <p>A customer matches when it satisfies both criteria:
+ *
+ * <ul>
+ * <li><b>name</b> &mdash; every whitespace-separated term of {@code name} occurs
+ * in the customer's first or last name, ignoring case and accents. A blank name
+ * matches every customer.
+ * <li><b>statuses</b> &mdash; the customer's status is one of the given ones. An
+ * empty set matches every customer.
+ * </ul>
+ *
+ * @param name     free text matched against first and last names; never null
+ * @param statuses the statuses to keep, empty for all; never null
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** The filter that keeps every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    public CustomerFilter(String name) {
+        this(name, Set.of());
+    }
+
+    /** True when this filter keeps every customer. */
+    public boolean isEmpty() {
+        return name.isBlank() && statuses.isEmpty();
+    }
+
+    /**
+     * The terms the name has to contain: the filter text split on whitespace and
+     * normalized. Empty when no name was given.
+     */
+    public List<String> nameTerms() {
+        String normalized = normalize(name).strip();
+        return normalized.isEmpty() ? List.of() : Arrays.asList(normalized.split("\\s+"));
+    }
+
+    /**
+     * This filter as a predicate. Building it once per query keeps the per-row
+     * work down to a couple of substring searches.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> wanted = statuses;
+        return customer -> matchesStatus(customer, wanted) && matchesName(customer, terms);
+    }
+
+    /** True when the given customer satisfies this filter. */
+    public boolean matches(Customer customer) {
+        return asPredicate().test(customer);
+    }
+
+    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> wanted) {
+        return wanted.isEmpty() || wanted.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        for (String term : terms) {
+            if (!first.contains(term) && !last.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /**
+     * Folds a string down to lower case ASCII-ish letters, so that
+     * {@code MAKINEN}, {@code makinen} and {@code Mäkinen} all compare equal.
+     */
+    static String normalize(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        StringBuilder result = new StringBuilder(decomposed.length());
+        for (int i = 0; i < decomposed.length(); i++) {
+            char c = decomposed.charAt(i);
+            if (isDiacritic(c)) {
+                continue;
+            }
+            // Letters that carry their accent inside the code point and so
+            // survive decomposition.
+            switch (c) {
+                case 'ø', 'Ø' -> result.append('o');
+                case 'đ', 'Đ', 'ð', 'Ð' -> result.append('d');
+                case 'ł', 'Ł' -> result.append('l');
+                case 'ı' -> result.append('i');
+                case 'æ', 'Æ' -> result.append("ae");
+                case 'œ', 'Œ' -> result.append("oe");
+                case 'ß' -> result.append("ss");
+                case 'þ', 'Þ' -> result.append("th");
+                default -> result.append(Character.toLowerCase(c));
+            }
+        }
+        return result.toString();
+    }
+
+    private static boolean isDiacritic(char c) {
+        int type = Character.getType(c);
+        return type == Character.NON_SPACING_MARK
+                || type == Character.COMBINING_SPACING_MARK
+                || type == Character.ENCLOSING_MARK;
+    }
+}
