+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+/**
+ * The same view in a real (headless) browser. This is where the two things a
+ * browserless test cannot see are checked: what the address bar says, and how
+ * many backend queries typing actually costs.
+ *
+ * <p>Named {@code *IT} so that the fast {@code mvn test} run stays browserless;
+ * run it with {@code mvn -o test -Dtest=CustomerListViewBrowserIT -DfailIfNoSpecifiedTests=false}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void typingFiltersTheListWithoutAQueryPerKeystroke() {
+        waitForGrid();
+        queryLog.clear();
+
+        // Really typed, one letter at a time, not pasted.
+        Locator input = nameField().getInputLocator();
+        input.click();
+        input.pressSequentially("virtanen", new Locator.PressSequentiallyOptions().setDelay(60));
+        waitForText("Showing 15 of 500");
+
+        assertEquals(15, grid().getTotalRowCount());
+        assertEquals(List.of(15), queryLog.countQueries(),
+                "Typing a name must not query the backend per keystroke");
+        assertTrue(queryLog.pageQueries().size() <= 3,
+                "Too many page queries for one name: " + queryLog.pageQueries());
+        assertTrue(queryLog.rowsFetched() <= 200,
+                "Filtering pulled " + queryLog.rowsFetched() + " rows over");
+    }
+
+    @Test
+    void theFilterEndsUpInTheAddressBar() {
+        waitForGrid();
+
+        nameField().setValue("vir");
+        waitForText("Showing 15 of 500");
+        waitForUrl("/?name=vir");
+
+        statusField().selectItems("ACTIVE", "CLOSED");
+        waitForText("Showing 10 of 500");
+        waitForUrl("/?name=vir&status=ACTIVE,CLOSED");
+        assertEquals(getUrl() + "/?name=vir&status=ACTIVE,CLOSED", page.url());
+
+        nameField().setValue("");
+        waitForText("Showing 333 of 500");
+        waitForUrl("/?status=ACTIVE,CLOSED");
+
+        statusField().deselectItems("ACTIVE", "CLOSED");
+        waitForText("Showing 500 of 500");
+        waitForUrl("/");
+        assertEquals(getUrl() + "/", page.url(), "An empty filter must leave no parameters behind");
+    }
+
+    @Test
+    void typingDoesNotFillUpTheBackButton() {
+        waitForGrid();
+        int before = historyLength();
+
+        nameField().setValue("virtanen");
+        waitForText("Showing 15 of 500");
+
+        assertEquals(before, historyLength(),
+                "Filtering must replace the URL, not push a history entry");
+    }
+
+    @Test
+    void aSharedUrlOpensTheFilteredList() {
+        page.navigate(getUrl() + "/?name=ada%20aal&status=ACTIVE");
+        waitForVaadin();
+        waitForText("Showing 1 of 500");
+
+        assertEquals("ada aal", nameField().getValue());
+        assertEquals(List.of("ACTIVE"), statusField().getSelectedItems());
+        assertEquals(1, grid().getTotalRowCount());
+    }
+
+    // --- Helpers -------------------------------------------------------------
+
+    private GridElement grid() {
+        return GridElement.get(page);
+    }
+
+    private TextFieldElement nameField() {
+        return new TextFieldElement(page.locator("vaadin-text-field"));
+    }
+
+    private MultiSelectComboBoxElement statusField() {
+        return MultiSelectComboBoxElement.getByLabel(page, "Status");
+    }
+
+    private void waitForGrid() {
+        waitForVaadin();
+        page.locator("vaadin-grid").first().waitFor();
+        waitForText("Showing 500 of 500");
+    }
+
+    private void waitForVaadin() {
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+    }
+
+    private void waitForText(String text) {
+        Locator locator = page.getByText(text, new Page.GetByTextOptions().setExact(true));
+        locator.first().waitFor();
+    }
+
+    private void waitForUrl(String pathAndQuery) {
+        page.waitForURL(getUrl() + pathAndQuery);
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("() => window.history.length")).intValue();
+    }
+}
